<h3 class="mb-4">مقدمو الخدمة</h3><div class="table-responsive"><table class="table table-hover bg-white"><thead><tr><th>المقدم</th><th>المهنة</th><th>التقييم</th><th>التوثيق</th><th>الخدمات المكتملة</th></tr></thead><tbody><?php foreach($providers as $p): ?><tr><td><?= e($p['name']??'') ?></td><td><?= e($p['profession']??'') ?></td><td><?= number_format((float)($p['avg_rating']??0),2) ?>/5</td><td><?= !empty($p['is_verified'])?'موثق':'غير موثق' ?></td><td><?= number_format((int)($p['completed_jobs']??0)) ?></td></tr><?php endforeach; ?></tbody></table></div>